  EXPECT_EQ(Escape("back\\slash"), "back\\\\slash");
}

TEST(EscapingTest, UnescapingReplacesEscapeSequences) {
  EXPECT_EQ(Unescape("two\\nlines"), "two\nlines");
  EXPECT_EQ(Unescape("back\\\\slash"), "back\\slash");
}

